// =============================================
// ETL AI AUTOMATION - FINAL DATA CLEANING
// Preserve all 50 student records
// =============================================

// Original CSV records
const originalItems = $("Extract from File").all();

// AI output records
const aiItems = $input.all();

// Convert text to Title Case
function titleCase(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\b\w/g, c => c.toUpperCase());
}

// Convert date to YYYY-MM-DD
function cleanDate(value) {
  const date = String(value ?? "").trim();

  if (!date) return "INVALID_DATE";

  let year, month, day;
  let match;

  // DD-MM-YYYY or DD/MM/YYYY
  match = date.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);

  if (match) {
    day = Number(match[1]);
    month = Number(match[2]);
    year = Number(match[3]);
  } else {
    // YYYY-MM-DD
    match = date.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);

    if (!match) return "INVALID_DATE";

    year = Number(match[1]);
    month = Number(match[2]);
    day = Number(match[3]);
  }

  const parsed = new Date(Date.UTC(year, month - 1, day));

  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() + 1 !== month ||
    parsed.getUTCDate() !== day
  ) {
    return "INVALID_DATE";
  }

  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

// Parse AI response safely
function parseAI(item) {
  try {
    let data = item?.json?.text ??
               item?.json?.output ??
               item?.json;

    if (typeof data === "string") {
      data = data
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/, "")
        .trim();

      const start = data.indexOf("{");
      const end = data.lastIndexOf("}");

      if (start === -1 || end <= start) {
        return null;
      }

      data = JSON.parse(data.slice(start, end + 1));
    }

    if (
      !data ||
      typeof data !== "object" ||
      Array.isArray(data) ||
      !data.Student_ID
    ) {
      return null;
    }

    return data;

  } catch (error) {
    return null;
  }
}

// Create a lookup using Student_ID
const aiLookup = new Map();

for (const item of aiItems) {
  const parsed = parseAI(item);

  if (parsed) {
    const id = String(parsed.Student_ID).trim();

    if (id && !aiLookup.has(id)) {
      aiLookup.set(id, parsed);
    }
  }
}

// Process all original CSV records
const cleanedData = originalItems.map((item, index) => {

  const original = item.json;

  const studentId = String(original.Student_ID ?? "").trim();

  // Use AI data only when Student_ID matches
  const aiData = aiLookup.get(studentId);

  // Preserve original identity
  const name = titleCase(original.Name);

  // Email
  const email = String(
    aiData?.Email ?? original.Email ?? ""
  ).trim().toLowerCase();

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  const cleanEmail = emailRegex.test(email)
    ? email
    : "INVALID_EMAIL";

  // Phone
  const phone = String(
    aiData?.Phone ?? original.Phone ?? ""
  ).replace(/\D/g, "");

  const cleanPhone = phone.length === 10
    ? phone
    : "MISSING";

  // Course
  const course = String(
    aiData?.Course ?? original.Course ?? ""
  ).trim().toLowerCase();

  const courseMap = {
    "python": "Python",
    "ml": "Machine Learning",
    "machine learning": "Machine Learning",
    "data science": "Data Science"
  };

  const cleanCourse = courseMap[course] ?? "UNKNOWN";

  // Fee Paid
  const feeValue = String(
    original.Fee_Paid ?? ""
  ).trim().toLowerCase();

  const feePaid = ["yes", "true", "1"].includes(feeValue);

  // City
  const city = titleCase(
    aiData?.City ?? original.City
  ) || "UNKNOWN";

  // Date: use original date to avoid AI date changes
  const enrolledDate = cleanDate(original.Enrolled_Date);

  return {
    json: {
      Student_ID: studentId,
      Name: name,
      Email: cleanEmail,
      Phone: cleanPhone,
      Course: cleanCourse,
      Fee_Paid: feePaid,
      City: city,
      Enrolled_Date: enrolledDate,
      Status: aiData ? "AI_CLEANED" : "JS_CLEANED"
    },
    pairedItem: { item: index }
  };

});

return cleanedData;
